import * as React from 'react';
import { useTranslation } from 'react-i18next';

import GameMap from 'components/ui/GameMap';
import { CountryLabelWithFlag } from 'components/wiki/CountryLabelWithFlag';
import WikiCard, { CardTable, CardTitle } from 'components/wiki/WikiCard';

const SeaCard = (props) => {
    const { sea, onNext, onPrevious, onClickCountry } = props;
    const { i18n, t } = useTranslation();

    if (!sea) {
        return null;
    }

    const borders =
        sea.borders && sea.borders.length
            ? sea.borders.map((country, index) => {
                  return (
                      <CountryLabelWithFlag
                          key={country.cca3}
                          country={country}
                          onClickCountry={onClickCountry}
                          language={i18n.language}
                      />
                  );
              })
            : '';

    const cardTableRows = [
        {
            label: t('Type'),
            value: sea.type.map((ty) => t(ty)),
        },
        {
            label: t('Borders'),
            value: borders,
        },
        ...(sea.area
            ? [
                  {
                      label: t('Area'),
                      value: (
                          <>
                              {sea.area} <small>{t('sq. meters')}</small>
                          </>
                      ),
                  },
              ]
            : []),
        ...(sea.depth
            ? [
                  {
                      label: t('Depth'),
                      value: (
                          <>
                              {sea.depth} <small>{t('meters')}</small>
                          </>
                      ),
                  },
              ]
            : []),
        ...(sea.volume
            ? [
                  {
                      label: t('Volume'),
                      value: (
                          <>
                              {sea.volume} <small>{t('cu. meters')}</small>
                          </>
                      ),
                  },
              ]
            : []),
    ];

    return (
        <WikiCard>
            <CardTitle title={sea.getName(i18n.language)} onPrevious={onPrevious} onNext={onNext} />
            <GameMap geoFileName={sea.key} geoFolder="geoSeas" withLabels={true} initialMapHeight="30vh" />
            <CardTable aria={`sea ${sea.getName(i18n.language)}`} rows={cardTableRows} />
        </WikiCard>
    );
};

export default SeaCard;
